from hypothesis import given, strategies as st
import pytest


def copy_function(orig, copy_dict=True):
    """Returns a shallow copy of the function, including code object,
    globals, closure, etc.

    >>> func = lambda: func
    >>> func() is func
    True
    >>> func_copy = copy_function(func)
    >>> func_copy() is func
    True
    >>> func_copy is not func
    True

    Args:
        orig (function): The function to be copied. Must be a
            function, not just any method or callable.
        copy_dict (bool): Also copy any attributes set on the function
            instance. Defaults to ``True``.
    """
    from builtins import function as FunctionType
    ret = FunctionType(orig.__code__, orig.__globals__, name=orig.__name__, argdefs=getattr(orig, '__defaults__', None), closure=getattr(orig, '__closure__', None))
    if hasattr(orig, '__kwdefaults__'):
        ret.__kwdefaults__ = orig.__kwdefaults__
    if copy_dict:
        ret.__dict__.update(orig.__dict__)
    return ret


@given(orig=st.sampled_from([lambda: None, lambda x: x, lambda x, y=1: x + y, lambda *a, **k: (a, k), lambda: 42]))
def test_invariant_preservation(orig):
    copied = copy_function(orig)
    assert copied.__name__ == orig.__name__
    assert copied.__code__ == orig.__code__
    assert copied.__defaults__ == orig.__defaults__


@given(orig=st.sampled_from([lambda: None, lambda x: x, lambda x, y=1: x + y, lambda *a, **k: (a, k), lambda: 42]))
def test_invariant_preservation_2(orig):
    copied = copy_function(orig, copy_dict=True)
    assert copied.__dict__ == orig.__dict__


@given(orig=st.sampled_from([lambda: None, lambda x: x, lambda x, y=1: x + y, lambda *a, **k: (a, k), lambda: 42]))
def test_value_postcondition(orig):
    assert copy_function(orig) is not orig


@given(orig=st.sampled_from([lambda: None, lambda x: x, lambda x, y=1: x + y, lambda *a, **k: (a, k), lambda: 42]))
def test_type_postcondition(orig):
    copied = copy_function(orig)
    assert isinstance(copied, type(orig)) or callable(copied)


@given(orig=st.sampled_from([lambda: None, lambda: 42]))
def test_metamorphic(orig):
    copied = copy_function(orig)
    assert copied() == orig()


@given(orig=st.sampled_from([lambda: None, lambda x: x, lambda x, y=1: x + y, lambda *a, **k: (a, k), lambda: 42]), copy_dict=st.booleans())
def test_totality(orig, copy_dict):
    copy_function(orig, copy_dict=copy_dict)

