from hypothesis import given, strategies as st
import pytest
from collections.abc import Iterable


def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    from collections.abc import Iterable
    for item in iterable:
        if isinstance(item, Iterable) and (not isinstance(item, (str, bytes))):
            yield from flatten_iter(item)
        else:
            yield item


@given(nested=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_idempotence(nested):
    first = list(flatten_iter(nested))
    second = list(flatten_iter(first))
    assert second == first


@given(nested=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_invariant_preservation(nested):
    def collect_leaves(x):
        if isinstance(x, Iterable) and not isinstance(x, (str, bytes)):
            result = []
            for item in x:
                result.extend(collect_leaves(item))
            return result
        else:
            return [x]

    def sort_key(v):
        return (str(type(v)), str(v))

    expected = sorted(collect_leaves(nested), key=sort_key)
    actual = sorted(list(flatten_iter(nested)), key=sort_key)
    assert actual == expected


@given(a=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20), b=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_metamorphic(a, b):
    combined = list(flatten_iter([a, b]))
    separate = list(flatten_iter([a])) + list(flatten_iter([b]))
    assert combined == separate


@given(nested=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_type_postcondition(nested):
    result = list(flatten_iter(nested))
    assert all(not isinstance(x, Iterable) or isinstance(x, (str, bytes)) for x in result)


@given(iterable=st.recursive(st.integers() | st.floats(allow_nan=False) | st.text(), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_totality(iterable):
    result = list(flatten_iter(iterable))
    assert isinstance(result, list)

from hypothesis import given, strategies as st
import pytest


def ceil(x, options=None):
    """Return the ceiling of *x*. If *options* is set, return the smallest
    integer or float from *options* that is greater than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> ceil(3.5, options=VALID_CABLE_CSA)
    4
    >>> ceil(4, options=VALID_CABLE_CSA)
    4
    """
    from math import ceil as _ceil
    import bisect
    if options is None:
        return _ceil(x)
    options = sorted(options)
    i = bisect.bisect_left(options, x)
    if i == len(options):
        raise ValueError('no ceil options greater than or equal to: %r' % x)
    return options[i]


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_value_postcondition(x):
    assert ceil(x) >= x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_value_postcondition_2(x, options):
    result = ceil(x, options)
    assert result in options
    assert result >= x


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    assert ceil(ceil(x)) == ceil(x)


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), options=st.lists(st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)), min_size=1, max_size=20))
def test_metamorphic(x, options):
    cx = ceil(x, options)
    y = cx
    assert ceil(y, options) == cx


@given(x=st.one_of(st.integers(min_value=-10**6, max_value=10**6), st.floats(min_value=-1e6, max_value=1e6, allow_nan=False, allow_infinity=False)))
def test_totality(x):
    ceil(x)

from hypothesis import given, strategies as st
import pytest


def alphanumcase(string):
    """Cuts all non-alphanumeric symbols,
    i.e. cuts all expect except 0-9, a-z and A-Z.

    Args:
        string: String to convert.

    Returns:
        string: String with cutted non-alphanumeric symbols.

    """
    import re
    return re.sub('\\W+', '', string)


@given(string=st.text())
def test_idempotence(string):
    assert alphanumcase(alphanumcase(string)) == alphanumcase(string)


@given(string=st.text())
def test_invariant_preservation(string):
    assert set(alphanumcase(string)) <= set(c for c in string if c.isalnum())


@given(string=st.text())
def test_value_postcondition(string):
    assert all(c.isalnum() for c in alphanumcase(string))


@given(string=st.text())
def test_type_postcondition(string):
    assert isinstance(alphanumcase(string), str)


@given(string=st.text())
def test_totality(string):
    alphanumcase(string)

from hypothesis import given, strategies as st
import pytest


def under2camel(under_string):
    """Converts an underscored string to camelcased. Useful for turning a
    function name into a class name.

    >>> under2camel('complex_tokenizer')
    'ComplexTokenizer'
    """
    return ''.join((w.capitalize() or '_' for w in under_string.split('_')))


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=50))
def test_type_postcondition(under_string):
    assert isinstance(under2camel(under_string), str)


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=50))
def test_idempotence(under_string):
    once = under2camel(under_string)
    if '_' not in once:
        assert under2camel(once) == once


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=50))
def test_invariant_preservation(under_string):
    assert len(under2camel(under_string)) <= len(under_string)


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=50))
def test_metamorphic(under_string):
    assert under2camel(under_string) == under2camel(under_string.lower())


@given(under_string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=0, max_size=50))
def test_totality(under_string):
    under2camel(under_string)

from hypothesis import given, strategies as st
import pytest


def unwrap_text(text, ending='\n\n'):
    """
    Unwrap text, the natural complement to :func:`textwrap.wrap`.

    >>> text = "Short \\n lines  \\nwrapped\\nsmall.\\n\\nAnother\\nparagraph."
    >>> unwrap_text(text)
    'Short lines wrapped small.\\n\\nAnother paragraph.'

    Args:
       text: A string to unwrap.
       ending (str): The string to join all unwrapped paragraphs
          by. Pass ``None`` to get the list. Defaults to '\\n\\n' for
          compatibility with Markdown and RST.

    """
    all_grafs = []
    cur_graf = []
    for line in text.splitlines():
        line = line.strip()
        if line:
            cur_graf.append(line)
        else:
            all_grafs.append(' '.join(cur_graf))
            cur_graf = []
    if cur_graf:
        all_grafs.append(' '.join(cur_graf))
    if ending is None:
        return all_grafs
    return ending.join(all_grafs)


@given(text=st.text())
def test_idempotence(text):
    assert unwrap_text(unwrap_text(text)) == unwrap_text(text)


@given(text=st.text(), ending=st.one_of(st.none(), st.text(alphabet=['\n', ' ', '\t', '-', ',', '.'], min_size=0, max_size=5), st.just('\n\n'), st.just(' ')))
def test_metamorphic(text, ending):
    if ending is not None:
        assert ending.join(unwrap_text(text, ending=None)) == unwrap_text(text, ending=ending)


@given(text=st.text())
def test_invariant_preservation(text):
    result = unwrap_text(text)
    for line in result.split('\n'):
        assert line == line.strip()
        assert '  ' not in line


@given(text=st.text(), ending=st.one_of(st.none(), st.text(alphabet=['\n', ' ', '\t', '-', ',', '.'], min_size=0, max_size=5), st.just('\n\n'), st.just(' ')))
def test_type_postcondition(text, ending):
    result = unwrap_text(text, ending=ending)
    if ending is None:
        assert isinstance(result, list)
    else:
        assert isinstance(result, str)


@given(text=st.text(), ending=st.one_of(st.none(), st.text(alphabet=['\n', ' ', '\t', '-', ',', '.'], min_size=0, max_size=5), st.just('\n\n'), st.just(' ')))
def test_totality(text, ending):
    unwrap_text(text, ending=ending)

