from hypothesis import given, strategies as st
import pytest


def camelize(string: str, uppercase_first_letter: bool=True) -> str:
    """
    Convert strings to CamelCase.

    Examples::

        >>> camelize("device_type")
        'DeviceType'
        >>> camelize("device_type", False)
        'deviceType'

    :func:`camelize` can be thought of as a inverse of :func:`underscore`,
    although there are some cases where that does not hold::

        >>> camelize(underscore("IOError"))
        'IoError'

    :param uppercase_first_letter: if set to `True` :func:`camelize` converts
        strings to UpperCamelCase. If set to `False` :func:`camelize` produces
        lowerCamelCase. Defaults to `True`.
    """
    import re
    if uppercase_first_letter:
        return re.sub('(?:^|_)(.)', lambda m: m.group(1).upper(), string)
    else:
        return string[0].lower() + camelize(string)[1:]


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=1))
def test_idempotence(string):
    assert camelize(camelize(string)) == camelize(string)


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=1))
def test_metamorphic(string):
    upper_result = camelize(string, True)
    lower_result = camelize(string, False)
    assert upper_result[0].islower() == False
    assert lower_result[0].islower() == True


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=1), uppercase_first_letter=st.booleans())
def test_type_postcondition(string, uppercase_first_letter):
    assert isinstance(camelize(string, uppercase_first_letter), str)


@given(string=st.text(alphabet=st.characters(whitelist_categories=('Ll','Lu','Nd'), whitelist_characters='_'), min_size=1), uppercase_first_letter=st.booleans())
def test_totality(string, uppercase_first_letter):
    camelize(string, uppercase_first_letter)

from hypothesis import given, strategies as st
import pytest


def ordinal(number: int) -> str:
    """
    Return the suffix that should be added to a number to denote the position
    in an ordered sequence such as 1st, 2nd, 3rd, 4th.

    Examples::

        >>> ordinal(1)
        'st'
        >>> ordinal(2)
        'nd'
        >>> ordinal(1002)
        'nd'
        >>> ordinal(1003)
        'rd'
        >>> ordinal(-11)
        'th'
        >>> ordinal(-1021)
        'st'

    """
    number = abs(int(number))
    if number % 100 in (11, 12, 13):
        return 'th'
    else:
        return {1: 'st', 2: 'nd', 3: 'rd'}.get(number % 10, 'th')


@given(number=st.integers(min_value=-10**12, max_value=10**12))
def test_value_postcondition(number):
    assert ordinal(number) in {'st', 'nd', 'rd', 'th'}


@given(number=st.integers(min_value=-10**12, max_value=10**12))
def test_metamorphic(number):
    assert ordinal(number) == ordinal(-number)


@given(number=st.integers(min_value=-10**12, max_value=10**12))
def test_metamorphic_2(number):
    assert ordinal(number) == ordinal(number + 100)


@given(number=st.integers(min_value=-10**12, max_value=10**12))
def test_type_postcondition(number):
    assert isinstance(ordinal(number), str)


@given(number=st.integers(min_value=-10**12, max_value=10**12))
def test_totality(number):
    ordinal(number)

