from hypothesis import given, strategies as st
import pytest


def subdict(d, keep=None, drop=None):
    """Compute the "subdictionary" of a dict, *d*.

    A subdict is to a dict what a subset is a to set. If *A* is a
    subdict of *B*, that means that all keys of *A* are present in
    *B*.

    Returns a new dict with any keys in *drop* removed, and any keys
    in *keep* still present, provided they were in the original
    dict. *keep* defaults to all keys, *drop* defaults to empty, so
    without one of these arguments, calling this function is
    equivalent to calling ``dict()``.

    >>> from pprint import pprint as pp
    >>> pp(subdict({'a': 1, 'b': 2}))
    {'a': 1, 'b': 2}
    >>> subdict({'a': 1, 'b': 2, 'c': 3}, drop=['b', 'c'])
    {'a': 1}
    >>> pp(subdict({'a': 1, 'b': 2, 'c': 3}, keep=['a', 'c']))
    {'a': 1, 'c': 3}

    """
    if keep is None:
        keep = d.keys()
    if drop is None:
        drop = []
    keys = set(keep) - set(drop)
    return type(d)([(k, v) for k, v in d.items() if k in keys])


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))))
def test_invariant_preservation(d, keep):
    result = subdict(d, keep=keep)
    assert set(result.keys()) <= set(d.keys())
    assert all(result[k] == d[k] for k in result)


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))))
def test_idempotence(d, keep, drop):
    first = subdict(d, keep=keep, drop=drop)
    second = subdict(first, keep=keep, drop=drop)
    assert second == first


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()))
def test_metamorphic(d):
    assert subdict(d) == dict(d)


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))))
def test_metamorphic_2(d, drop):
    result = subdict(d, drop=drop)
    expected_keys = set(d.keys()) - set(drop or [])
    assert set(result.keys()) == expected_keys


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))))
def test_type_postcondition(d, keep, drop):
    assert type(subdict(d, keep=keep, drop=drop)) == type(d)


@given(d=st.dictionaries(st.text(min_size=1, max_size=5), st.integers()), keep=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))), drop=st.one_of(st.none(), st.lists(st.text(min_size=1, max_size=5))))
def test_totality(d, keep, drop):
    subdict(d, keep=keep, drop=drop)

from hypothesis import given, strategies as st
import pytest


def construct_format_field_str(fname, fspec, conv):
    """
    Constructs a format field string from the field name, spec, and
    conversion character (``fname``, ``fspec``, ``conv``). See Python
