from hypothesis import given, strategies as st
import pytest
import sys


def get_module_callables(mod, ignore=None):
    """Returns two maps of (*types*, *funcs*) from *mod*, optionally
    ignoring based on the :class:`bool` return value of the *ignore*
    callable. *mod* can be a string name of a module in
    :data:`sys.modules` or the module instance itself.
    """
    import sys
    if isinstance(mod, str):
        mod = sys.modules[mod]
    types, funcs = ({}, {})
    for attr_name in dir(mod):
        if ignore and ignore(attr_name):
            continue
        try:
            attr = getattr(mod, attr_name)
        except Exception:
            continue
        try:
            attr_mod_name = attr.__module__
        except AttributeError:
            continue
        if attr_mod_name != mod.__name__:
            continue
        if isinstance(attr, type):
            types[attr_name] = attr
        elif callable(attr):
            funcs[attr_name] = attr
    return (types, funcs)


@given(mod=st.sampled_from(sorted([m for m in sys.modules if sys.modules[m] is not None])), ignore=st.none() | st.sampled_from([lambda x: False, lambda x: True, lambda x: isinstance(x, type), lambda x: not isinstance(x, type)]))
def test_type_postcondition(mod, ignore):
    types, funcs = get_module_callables(mod, ignore)
    assert isinstance(types, dict) and isinstance(funcs, dict)
    assert all(isinstance(v, type) for v in types.values())
    assert all(callable(v) for v in funcs.values())


@given(mod=st.sampled_from(sorted([m for m in sys.modules if sys.modules[m] is not None])), ignore=st.none() | st.sampled_from([lambda x: False, lambda x: True, lambda x: isinstance(x, type), lambda x: not isinstance(x, type)]))
def test_invariant_preservation(mod, ignore):
    types, funcs = get_module_callables(mod, ignore)
    assert set(types.keys()) & set(funcs.keys()) == set()
    mod_name = mod if isinstance(mod, str) else mod.__name__
    mod_obj = sys.modules[mod_name] if isinstance(mod, str) else mod
    for k in list(types) + list(funcs):
        assert getattr(mod_obj, k).__module__ == mod_name


@given(mod=st.sampled_from(sorted([m for m in sys.modules if sys.modules[m] is not None])), ignore=st.none() | st.sampled_from([lambda x: False, lambda x: True, lambda x: isinstance(x, type), lambda x: not isinstance(x, type)]))
def test_totality(mod, ignore):
    get_module_callables(mod, ignore)


@given(mod=st.sampled_from(sorted([m for m in sys.modules if sys.modules[m] is not None])))
def test_metamorphic(mod):
    mod_instance = sys.modules[mod]
    assert get_module_callables(mod_instance) == get_module_callables(mod_instance.__name__)

