    if step <= 0:
        return
    real_start = 0.0 if start is None else start
    real_stop = stop if start is None else start
    real_stop = stop * 1.0 if start is None else stop
    # Compute actual start/stop as function does
    if start is None:
        s, e = 0.0, stop * 1.0
    else:
        s, e = start * 1.0, stop * 1.0
    result = list(xfrange(stop, start, step))
    assert all(s <= x < e for x in result)


