def test_idempotence(x, lower, upper):
    if lower <= upper:
        once = clamp(x, lower, upper)
        twice = clamp(once, lower, upper)
        assert twice == once


@given(x=st.floats(allow_nan=False), lower=st.floats(allow_nan=False, allow_infinity=True), upper=st.floats(allow_nan=False, allow_infinity=True))
def test_metamorphic(x, lower, upper):
    if lower <= upper and lower <= x <= upper:
        assert clamp(x, lower, upper) == x


