@given(x=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, width=64)), y=st.one_of(st.integers(min_value=-10**9, max_value=10**9), st.floats(allow_nan=False, allow_infinity=False, width=64)))
