from hypothesis import given, strategies as st
import pytest


def is_ascii(text):
    """Check if a string or bytestring, *text*, is composed of ascii
    characters only. Raises :exc:`ValueError` if argument is not text.

    Args:
        text (str): The string to be checked.

    >>> is_ascii('Beyoncé')
    False
    >>> is_ascii('Beyonce')
    True
    """
    if isinstance(text, str):
        try:
            text.encode('ascii')
        except UnicodeEncodeError:
            return False
    elif isinstance(text, bytes):
        try:
            text.decode('ascii')
        except UnicodeDecodeError:
            return False
    else:
        raise ValueError('expected text or bytes, not %r' % type(text))
    return True


@given(text=st.one_of(st.text(), st.binary()))
def test_type_postcondition(text):
    assert isinstance(is_ascii(text), bool)


@given(s=st.text())
def test_metamorphic(s):
    if all(ord(c) < 128 for c in s):
        assert is_ascii(s) == True
    if any(ord(c) >= 128 for c in s):
        assert is_ascii(s) == False


@given(s=st.text(alphabet=st.characters(max_codepoint=127)))
def test_invariant_preservation(s):
    assert is_ascii(s.encode('ascii')) == is_ascii(s)


@given(text=st.one_of(st.text(), st.binary()))
def test_totality(text):
    is_ascii(text)

from hypothesis import given, strategies as st
import pytest
import uuid


def is_uuid(obj, version=4):
    """Check the argument is either a valid UUID object or string.

    Args:
        obj (object): The test target. Strings and UUID objects supported.
        version (int): The target UUID version, set to 0 to skip version check.

    >>> is_uuid('e682ccca-5a4c-4ef2-9711-73f9ad1e15ea')
    True
    >>> is_uuid('0221f0d9-d4b9-11e5-a478-10ddb1c2feb9')
    False
    >>> is_uuid('0221f0d9-d4b9-11e5-a478-10ddb1c2feb9', version=1)
    True
    """
    import uuid
    if not isinstance(obj, uuid.UUID):
        try:
            obj = uuid.UUID(obj)
        except (TypeError, ValueError, AttributeError):
            return False
    if version and obj.version != int(version):
        return False
    return True


