def test_value_postcondition(range_string, delim, range_delim):
    result = parse_int_list(range_string, delim, range_delim)
    assert all(isinstance(v, int) and v > 0 for v in result)
    assert result == sorted(result)


@given(range_string=st.lists(st.one_of(st.integers(min_value=1, max_value=1000).map(str), st.tuples(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000)).map(lambda t: f"{min(t)}-{max(t)}")), min_size=1, max_size=10).map(lambda parts: ','.join(parts)), delim=st.just(','), range_delim=st.just('-'))
def test_type_postcondition(range_string, delim, range_delim):
    result = parse_int_list(range_string, delim, range_delim)
    assert isinstance(result, list)
    assert all(isinstance(x, int) for x in result)


@given(range_string=st.lists(st.one_of(st.integers(min_value=1, max_value=1000).map(str), st.tuples(st.integers(min_value=1, max_value=1000), st.integers(min_value=1, max_value=1000)).map(lambda t: f"{min(t)}-{max(t)}")), min_size=1, max_size=10).map(lambda parts: ','.join(parts)), delim=st.just(','), range_delim=st.just('-'))
def test_totality(range_string, delim, range_delim):
    parse_int_list(range_string, delim, range_delim)

from hypothesis import given, strategies as st
import pytest


def removeprefix(text: str, prefix: str) -> str:
    """
    Remove `prefix` from start of `text` if present.

    Backport of `str.removeprefix` for Python versions less than 3.9.

    Args:
        text: A string to remove the prefix from.
        prefix: The string to remove from the beginning of `text`.
    """
    if text.startswith(prefix):
        return text[len(prefix):]
    return text


